/* 水果机高清标志位图案资源库 (Base64 预置) */
const ASSET_IMAGES = {
  "apple": "data:image/png;base64,",
  "orange": "data:image/png;base64,",
  "lemon": "data:image/png;base64,",
  "bell": "data:image/png;base64,",
  "watermelon": "data:image/png;base64,",
  "star": "data:image/png;base64,",
  "seven": "data:image/png;base64,",
  "bar": "data:image/png;base64,",
  "ingots": "data:image/png;base64,",
};

const IMGS = {};
for (const [key, src] of Object.entries(ASSET_IMAGES)) {
  const img = new Image();
  img.src = src;
  IMGS[key] = img;
}

if (typeof window !== 'undefined') {
  window.IMGS = IMGS;
  window.ASSET_IMAGES = ASSET_IMAGES;
}
if (typeof globalThis !== 'undefined') {
  globalThis.IMGS = IMGS;
  globalThis.ASSET_IMAGES = ASSET_IMAGES;
}
